create table xxventuri.eba_sales_products_del_hist (
    hist_id                number,
    product_id             number,
    row_key                varchar2(255 byte),
    product_name           varchar2(255 byte),
    product_description    varchar2(4000 byte),
    product_family_id      number,
    product_sku            varchar2(255 byte),
    product_price          number,
    product_type_id        number,
    currency_type          varchar2(50 byte),
    catalogue_no           varchar2(500 byte),
    att_mimetype           varchar2(255 byte),
    att_filename           varchar2(255 byte),
    product_cost           number,
    product_currency_type  varchar2(10 byte),
    brand_id               number,
    unit_of_measure        number,
    lead_time              number,
    minimum_order_quantity number,
    duration_type          varchar2(20 byte),
    stock_id               number,
    status                 varchar2(10 byte),
    product_group          varchar2(200 byte),
    location               varchar2(255 byte),
    deleted_by             varchar2(255 byte),
    deleted_on             timestamp(6)
);

alter table xxventuri.eba_sales_products_del_hist add primary key ( hist_id )
    using index enable;


